  if (typeof value.desc !== 'string' || value.desc.trim().length === 0) return false;
  if (!['critical', 'high', 'medium', 'low'].includes(String(value.severity))) return false;
  if (!['happy', 'edge', 'adversarial', 'missing'].includes(String(value.category))) return false;
