  if (value.evidenceState === 'suspected') {
    if (typeof value.uncertaintyReason !== 'string' || value.uncertaintyReason.trim().length === 0) return false;
  } else if (value.uncertaintyReason !== undefined) {
    return false;
  }
  return true;
}

